#include <stdio.h>
#include <stdlib.h>

#define MAX_E 1000005
#define MAX_PAIRS 100005

typedef struct {
    int u, v;
} Pair;

Pair same_group[MAX_PAIRS];
Pair diff_group[MAX_PAIRS];
int group_id[MAX_E];

// Fast I/O
static inline int read_int() {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) {
        c = getchar_unlocked();
    }
    if (c == EOF) return 0;
    int res = 0;
    while (c >= '0' && c <= '9') {
        res = res * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return res;
}

int main() {
    int E = read_int();
    int M = read_int();
    int D = read_int();

    for (int i = 0; i < M; i++) {
        same_group[i].u = read_int();
        same_group[i].v = read_int();
    }

    for (int i = 0; i < D; i++) {
        diff_group[i].u = read_int();
        diff_group[i].v = read_int();
    }

    int num_groups = E / 3;
    for (int g = 1; g <= num_groups; g++) {
        int i = read_int();
        int j = read_int();
        int k = read_int();
        group_id[i] = g;
        group_id[j] = g;
        group_id[k] = g;
    }

    int violations = 0;

    for (int i = 0; i < M; i++) {
        if (group_id[same_group[i].u] != group_id[same_group[i].v]) {
            violations++;
        }
    }

    for (int i = 0; i < D; i++) {
        if (group_id[diff_group[i].u] == group_id[diff_group[i].v]) {
            violations++;
        }
    }

    printf("%d\n", violations);

    return 0;
}
